<section class="admin-page-head"><div><p class="admin-kicker">SUCURSALES</p><h1>Sucursales</h1><p>Administra los datos de contacto y operación de cada ubicación.</p></div><?php if ($capabilities['branches.create'] ?? false): ?><a class="admin-primary-button" href="/admin/branches/create">+ Nueva sucursal</a><?php endif ?></section>
<section class="admin-panel admin-table-panel"><?php if ($page->items === []): ?><div class="admin-empty"><strong>No hay sucursales disponibles.</strong><span>Crea la primera sucursal para comenzar a organizar la operación.</span></div><?php else: ?><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Sucursal</th><th>Contacto</th><th>Estado</th><th><span class="sr-only">Acciones</span></th></tr></thead><tbody><?php foreach ($page->items as $branch): ?><tr><td><strong><?= e($branch->name) ?></strong><small><?= e($branch->code) ?></small></td><td><?= e($branch->email ?? 'Sin correo') ?><small><?= e($branch->phone ?? 'Sin teléfono') ?></small></td><td><span class="admin-status <?= $branch->active ? 'is-active' : '' ?>"><?= $branch->active ? 'Activa' : 'Inactiva' ?></span></td><td class="admin-actions"><a class="admin-secondary-button" href="/admin/branches/detail?id=<?= e($branch->id) ?>">Consultar</a><?php if ($capabilities['branches.edit'] ?? false): ?><a class="admin-secondary-button" href="/admin/branches/edit?id=<?= e($branch->id) ?>">Editar</a><?php endif ?><?php if ($capabilities['branches.status'] ?? false): ?><form method="post" action="/admin/branches/status"><input type="hidden" name="_token" value="<?= e($csrf) ?>"><input type="hidden" name="id" value="<?= e($branch->id) ?>"><input type="hidden" name="active" value="<?= $branch->active ? '0' : '1' ?>"><button class="admin-quiet-button" type="submit" data-confirm="<?= $branch->active ? '¿Desactivar esta sucursal?' : '¿Activar esta sucursal?' ?>"><?= $branch->active ? 'Desactivar' : 'Activar' ?></button></form><?php endif ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section>
